from typing import Type, Callable
from rclpy.node import Node as ROS2BaseNode
from ..logger.logger import logger


class ROS2Service:
    def __init__(
        self,
        node: ROS2BaseNode,
        srv_type: Type,
        service: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS2服务服务器

        Args:
            node: ROS2BaseNode实例
            srv_type: 服务类型
            service: 服务名称
            callback: 回调函数
            qos_profile: QoS配置
            **kwargs: 其他参数传递给create_service
        """
        self._node = node
        self._srv_type = srv_type
        self._service = service
        self._callback = callback
        self._server = node.create_service(srv_type, service, callback, **kwargs)

    @property
    def service(self) -> str:
        """获取服务名称"""
        return self._service

    @property
    def srv_type(self) -> Type:
        """获取服务类型"""
        return self._srv_type

    def destroy(self):
        """销毁服务服务器"""
        self._node.destroy_service(self._server)
